package mod.cdv.tnpc.tactical;
import fixture.*;import net.minecraft.world.entity.*;import net.minecraft.world.item.ItemStack;import net.minecraft.world.phys.Vec3;import net.minecraft.nbt.CompoundTag;import com.raiiiden.warborn.common.item.WBArmorItem;import com.raiiiden.warborn.common.util.StackData;import net.neoforged.neoforge.network.PacketDistributor;
public class MotionChecks26 {
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 public static class World extends fixture.World {public boolean collision=true,floor=true;public Object getEntity(int id){return entities.stream().filter(n->n.id==id).findFirst().orElse(null);}public boolean noCollision(Object entity,Box box){return collision;}public fixture.BlockState getBlockState(Object p){return new fixture.BlockState(floor?"minecraft:stone":"minecraft:air");}}
 public static class Look extends fixture.Entity {public boolean wanted;public double tx,ty,tz;public Look(World w){super(w);}public void setLookAt(double x,double y,double z,float yaw,float pitch){wanted=true;tx=x;ty=y;tz=z;}}
 public static class Soldier extends TacticsChecks24.Soldier {public boolean hasEffect(Object effect){return vision;}public boolean aiming;public void aim(boolean v){aiming=v;}public float yHeadRotO,yBodyRot,yBodyRotO,yRotO;public boolean grounded=true,water;public Vec3 delta=new Vec3(0,0,0);public Look look;public Soldier(World w){super(w);look=new Look(w);}public Look getLookControl(){return look;}public void setYBodyRot(float f){yBodyRot=f;}public boolean isSwimming(){return swim;}public boolean onGround(){return grounded;}public boolean isInWater(){return water;}public Vec3 getDeltaMovement(){return delta;}public void setDeltaMovement(Vec3 v){delta=v;}}
 static Soldier actor(World w,int role,long seed)throws Exception{Soldier s=new Soldier(w);s.uuid=new java.util.UUID(0,seed);CompoundTag tag=new CompoundTag();tag.putInt("npc22_role",role);Roles22.read(s,tag);Social.init(s);s.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack("tacz:gun",1));return s;}
 public static void main(String[]args)throws Exception{World w=new World();Soldier s=actor(w,3,1);TacticsChecks24.Target target=new TacticsChecks24.Target(w);target.x=12;target.y=3;double error=Combat26.face(s,target);ok(s.look.wanted&&Math.abs(s.look.tx-12)<1e-6,"combat submits real look control target");ok(Math.abs(s.look.ty-(3+1.8*.52))<1e-5,"look and aim share target chest point");for(int i=0;i<6;i++)Combat26.face(s,target);ok(Math.abs(s.getYRot()+90)<.01,"head/body converge on target instead of travel yaw");ok(s.getXRot()<0,"look up toward raised target");Soldier fake=actor(w,3,7);s.yHeadRotO=-85;Client26.pose(s,fake);ok(fake.getYRot()==s.getYHeadRot()&&fake.yBodyRot==s.getYHeadRot(),"rendered gun and torso follow head direction");ok(fake.getXRot()==s.getXRot(),"rendered vertical aim retained");
 CalmBrain.state(s).target=target;s.setYRot(90);s.setYHeadRot(90);s.setYBodyRot(90);Combat26.finishTick(s);ok(Math.abs(s.getYRot()+90)<.01&&s.getYHeadRot()==s.yBodyRot,"post-control tick defeats travel direction and head clamp overwrite");ok(s.aiming,"weapon remains raised in combat");
 Soldier unknownClient=new Soldier(w);unknownClient.pose=Pose.SWIMMING;ok(Roles22.role(unknownClient)==-1,"client does not need synchronized server role tags");Client26.pose(unknownClient,fake);ok(fake.swimAmount==1&&!fake.swim,"prone body pose follows synchronized pose without server-only role");
 target.y=0;s.hurtTime=6;int before=PacketDistributor.sent;ok(Combat26.slide(s,target,false,20),"under-fire tactical slide begins");ok(s.pose.toString().equals("SWIMMING")&&!s.swim,"slide uses ground stance, not swim motion");ok(Math.hypot(s.delta.x(),s.delta.z())>0&&s.delta.y()==0,"slide is horizontal with conserved gravity");ok(((mod.cdv.tnpc.network.AnimationPacket)PacketDistributor.packet).animation()==4&&PacketDistributor.sent==before+1,"byte-coded slide action synchronized once");double speed=Math.hypot(s.delta.x(),s.delta.z());ok(Combat26.slide(s,target,false,26)&&Math.hypot(s.delta.x(),s.delta.z())<.32,"slide decelerates");ok(!Combat26.slide(s,target,false,32)&&s.pose.toString().equals("STANDING"),"slide ends and restores standing");ok(!Combat26.slide(s,target,false,33),"slide cooldown prevents spamming");Soldier wall=actor(w,3,3);wall.hurtTime=5;w.collision=false;ok(!Combat26.slide(wall,target,false,100),"wall blocks slide");w.collision=true;w.floor=false;Soldier ledge=actor(w,3,9);ledge.hurtTime=5;ok(!Combat26.slide(ledge,target,false,100),"no slide over unsupported ledge");w.floor=true;
 Soldier nvg=actor(w,3,11);Roles22.gear(nvg,new java.util.Random(1));w.now=200;w.night=false;w.brightness=15;Combat26.equipment(nvg);ok(nvg.vision,"NVG active in daylight as requested");ok(!StackData.get(nvg.getItemBySlot(EquipmentSlot.HEAD)).getBoolean("helmet_top_open"),"NVG physically lowered");ok(nvg.getOffhandItem().isEmpty(),"NVG profile does not also hold torch");var battery=WBArmorItem.getInsertedBattery(nvg.getItemBySlot(EquipmentSlot.HEAD));int power=StackData.get(battery).getInt("BatteryEnergy");Combat26.equipment(nvg);ok(StackData.get(battery).getInt("BatteryEnergy")==power,"equipment rate limited once per second");
 Soldier light=actor(w,3,12);Roles22.gear(light,new java.util.Random(1));Combat26.equipment(light);ok(!light.vision&&light.getOffhandItem().id.equals("flashlight:flashlight"),"no-NVG military profile uses flashlight");ok(WBArmorItem.getInsertedGoggles(light.getItemBySlot(EquipmentSlot.HEAD)).isEmpty(),"torch profile removes optional goggles from mount");ok(light.bag.stream().anyMatch(i->i.id.equals("fracturepoint:nvg_goggles")),"removed goggles preserved as inventory equipment");StackData.get(battery).putInt("BatteryEnergy",0);w.now=220;Combat26.equipment(nvg);ok(!nvg.vision&&nvg.getOffhandItem().id.equals("flashlight:flashlight"),"empty NVG battery falls back to light");Soldier civilian=actor(w,1,17);Combat26.equipment(civilian);ok(civilian.getOffhandItem().id.equals("flashlight:flashlight"),"survivor without NVG also gets flashlight");
 before=PacketDistributor.sent;Combat26.shot(civilian,"FAIL");ok(PacketDistributor.sent==before,"failed shot has no flash");Combat26.shot(civilian,"SUCCESS");ok(PacketDistributor.sent==before+1&&((mod.cdv.tnpc.network.AnimationPacket)PacketDistributor.packet).animation()==3,"every successful NPC shot sends native byte action, including neutral defense");net.minecraft.client.Minecraft.getInstance().level=w;Client26.packet(PacketDistributor.packet);ok(Client26.FIRES.containsKey(civilian),"client fires only on received shot event");Client26.packet(new mod.cdv.tnpc.network.AnimationPacket((byte)4,civilian.id));ok(Client26.sliding(civilian),"client slide animation starts");Client26.packet(new mod.cdv.tnpc.network.AnimationPacket((byte)5,civilian.id));ok(!Client26.sliding(civilian),"client slide animation stops");
 target.x=12;civilian.vision=true;ok(Combat26.vision(true,civilian,target),"neutral defenders also benefit from equipped night vision");ok(!Combat26.vision(false,civilian,target),"optics never bypass a wall");civilian.vision=false;ok(Combat26.vision(true,civilian,target),"held flashlight supports dark target perception");target.x=30;ok(!Combat26.vision(true,civilian,target),"tactical vision respects native 24-block acquisition radius");
 w.now=260;StackData.get(battery).putInt("BatteryEnergy",100);Combat26.equipment(nvg);ok(nvg.getOffhandItem().isEmpty()&&nvg.bag.stream().filter(i->i.id.equals("flashlight:flashlight")).count()==1,"returning to NVG stores one existing torch");w.now=280;StackData.get(battery).putInt("BatteryEnergy",0);Combat26.equipment(nvg);ok(nvg.getOffhandItem().id.equals("flashlight:flashlight")&&nvg.bag.stream().noneMatch(i->i.id.equals("flashlight:flashlight")),"fallback reuses stored torch without duplication");civilian.setItemSlot(EquipmentSlot.OFFHAND,ItemStack.EMPTY);Combat26.equipment(civilian);ok(civilian.getOffhandItem().isEmpty(),"looted light is not regenerated every tick");
 target.x=12;Soldier heard=actor(w,3,41);heard.tag.putLong("npc26_threat_until",1020);ok(Combat26.slide(heard,target,false,1000),"nearby incoming shot can trigger evasive slide even without damage");
 System.out.println("LOOK_CONTROL_RENDER_ALIGNMENT_SLIDE_GRAVITY_COLLISION_NVG_FALLBACK_BYTE_PACKET_CHECKS="+checks);}
}
